import{_ as n,o as a,c as p,ai as l}from"./chunks/framework.Ba-VnP44.js";const m=JSON.parse('{"title":"01 项目初始化与 AI 接入","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/coding-sop/01-project-init.md","filePath":"ai/productivity/coding-sop/01-project-init.md"}'),e={name:"ai/productivity/coding-sop/01-project-init.md"};function i(r,s,t,c,b,d){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="_01-项目初始化与-ai-接入" tabindex="-1">01 项目初始化与 AI 接入 <a class="header-anchor" href="#_01-项目初始化与-ai-接入" aria-label="Permalink to “01 项目初始化与 AI 接入”">​</a></h1><blockquote><p>新项目开始前，让 AI 建立正确的项目开发环境；接手老项目时，让 AI 先理解现状再动手。目标是避免每次开发都重新解释项目，减少盲目扫描和错误修改。</p></blockquote><h2 id="一、先判断当前属于哪种情况" tabindex="-1">一、先判断当前属于哪种情况 <a class="header-anchor" href="#一、先判断当前属于哪种情况" aria-label="Permalink to “一、先判断当前属于哪种情况”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>操作方式</th></tr></thead><tbody><tr><td>全新项目，代码还没开始写</td><td>新项目初始化</td></tr><tr><td>已有脚手架，但尚未正式开发</td><td>检查现有结构，补充项目约定</td></tr><tr><td>接手别人开发的项目</td><td>老项目接管</td></tr><tr><td>已经开发了一段时间，但 AI 经常理解错误</td><td>补充项目上下文与规则</td></tr><tr><td>小型一次性项目</td><td>只做最小必要准备，不建立完整体系</td></tr></tbody></table><p>不要每个项目都创建一套庞大的文档。</p><p>项目初始化的核心任务只有三个：</p><ol><li>让 AI 知道项目是什么。</li><li>让 AI 知道如何正确开发和验证。</li><li>让 AI 知道哪些事情不能擅自做。</li></ol><h2 id="二、新项目初始化" tabindex="-1">二、新项目初始化 <a class="header-anchor" href="#二、新项目初始化" aria-label="Permalink to “二、新项目初始化”">​</a></h2><h3 id="_2-1-执行步骤" tabindex="-1">2.1 执行步骤 <a class="header-anchor" href="#_2-1-执行步骤" aria-label="Permalink to “2.1 执行步骤”">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>AI 要做什么</th><th>产出</th></tr></thead><tbody><tr><td>1</td><td>明确项目目标、用户和核心功能</td><td>项目目标</td></tr><tr><td>2</td><td>确认技术栈与运行环境</td><td>技术约定</td></tr><tr><td>3</td><td>检查或建立项目目录结构</td><td>项目骨架</td></tr><tr><td>4</td><td>确定开发、构建和测试命令</td><td>命令清单</td></tr><tr><td>5</td><td>确定代码规范和修改边界</td><td>项目规则</td></tr><tr><td>6</td><td>检查开发环境是否可用</td><td>环境检查结果</td></tr><tr><td>7</td><td>整理必要的项目上下文</td><td>项目说明</td></tr></tbody></table><h3 id="_2-2-新项目初始化提示词" tabindex="-1">2.2 新项目初始化提示词 <a class="header-anchor" href="#_2-2-新项目初始化提示词" aria-label="Permalink to “2.2 新项目初始化提示词”">​</a></h3><p>适用于 Cursor、WorkBuddy 等 AI 编程工具。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>现在准备开始一个新项目。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你的任务是协助我完成项目初始化，但暂时不要直接大规模编写业务代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步：明确项目目标</span></span>
<span class="line"><span>请先了解：</span></span>
<span class="line"><span>1. 项目要解决什么问题？</span></span>
<span class="line"><span>2. 主要用户是谁？</span></span>
<span class="line"><span>3. 核心业务功能有哪些？</span></span>
<span class="line"><span>4. 当前已经确定的技术选型是什么？</span></span>
<span class="line"><span>5. 有哪些明确的开发约束？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果现有信息足够，不要重复询问。</span></span>
<span class="line"><span>如果存在关键缺失，一次性列出需要我确认的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步：检查现有环境</span></span>
<span class="line"><span>检查当前工作目录：</span></span>
<span class="line"><span>- 是否已经存在项目文件？</span></span>
<span class="line"><span>- 是否已经有技术脚手架？</span></span>
<span class="line"><span>- 是否存在 Git 仓库？</span></span>
<span class="line"><span>- 是否已有项目规则文件？</span></span>
<span class="line"><span>- 是否已经安装必要依赖？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要覆盖或删除已有内容。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步：提出初始化方案</span></span>
<span class="line"><span>给出：</span></span>
<span class="line"><span>1. 推荐目录结构。</span></span>
<span class="line"><span>2. 技术栈与依赖建议。</span></span>
<span class="line"><span>3. 开发、构建、测试命令。</span></span>
<span class="line"><span>4. 必要的项目规则。</span></span>
<span class="line"><span>5. 当前阶段需要创建的文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第四步：控制初始化范围</span></span>
<span class="line"><span>只创建当前阶段真正需要的内容。</span></span>
<span class="line"><span>不要预建大量空文档。</span></span>
<span class="line"><span>不要为了使用 Agent、Skills 或 MCP 而强行增加配置。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第五步：执行环境检查</span></span>
<span class="line"><span>在获得必要授权后，执行初始化和环境检查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终向我报告：</span></span>
<span class="line"><span>- 已完成的初始化内容。</span></span>
<span class="line"><span>- 项目目录结构。</span></span>
<span class="line"><span>- 技术栈。</span></span>
<span class="line"><span>- 开发和测试命令。</span></span>
<span class="line"><span>- 尚未解决的问题。</span></span>
<span class="line"><span>- 下一步建议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>特别要求：</span></span>
<span class="line"><span>不要把尚未确认的技术选型写成既定事实。</span></span>
<span class="line"><span>不要在没有确认的情况下执行高风险操作。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br></div></div><h3 id="_2-3-新项目初始化完成标准" tabindex="-1">2.3 新项目初始化完成标准 <a class="header-anchor" href="#_2-3-新项目初始化完成标准" aria-label="Permalink to “2.3 新项目初始化完成标准”">​</a></h3><ul><li>项目目标已经明确。</li><li>技术栈已经确认。</li><li>项目目录结构合理。</li><li>开发环境可以正常运行。</li><li>开发和构建命令已验证。</li><li>测试方式已明确。</li><li>必要的项目规则已建立。</li><li>没有创建无意义的空文档或复杂配置。</li></ul><p>满足当前阶段所需的项目条件即可开始业务开发，不必追求所有事项一次性完美。</p><h2 id="三、老项目接管" tabindex="-1">三、老项目接管 <a class="header-anchor" href="#三、老项目接管" aria-label="Permalink to “三、老项目接管”">​</a></h2><p>老项目和新项目最大的区别是：</p><p><strong>新项目可以设计结构，老项目必须尊重现状。</strong></p><p>AI 不能因为认为某种架构更先进，就随意重构已有系统。</p><h3 id="_3-1-老项目接管步骤" tabindex="-1">3.1 老项目接管步骤 <a class="header-anchor" href="#_3-1-老项目接管步骤" aria-label="Permalink to “3.1 老项目接管步骤”">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>检查内容</th><th>产出</th></tr></thead><tbody><tr><td>1</td><td>项目目录与模块划分</td><td>项目结构</td></tr><tr><td>2</td><td>技术栈、依赖和版本</td><td>技术环境</td></tr><tr><td>3</td><td>启动、构建和测试方式</td><td>命令清单</td></tr><tr><td>4</td><td>核心业务模块与调用关系</td><td>业务地图</td></tr><tr><td>5</td><td>数据库、接口和外部依赖</td><td>关键依赖清单</td></tr><tr><td>6</td><td>代码规范和已有规则</td><td>开发约定</td></tr><tr><td>7</td><td>当前已知问题和风险</td><td>风险清单</td></tr><tr><td>8</td><td>与当前任务相关的代码位置</td><td>任务上下文</td></tr><tr><td>9</td><td>汇总并检查认知准确性</td><td>项目接入报告</td></tr></tbody></table><p>不要求一次性理解整个系统。</p><p>先掌握项目整体结构，再围绕实际开发任务深入对应模块。</p><h3 id="_3-2-老项目接管提示词" tabindex="-1">3.2 老项目接管提示词 <a class="header-anchor" href="#_3-2-老项目接管提示词" aria-label="Permalink to “3.2 老项目接管提示词”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你现在需要接管一个已经存在的软件项目。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>本轮任务是：理解项目现状，建立后续开发所需的上下文。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>暂时不要修改业务代码，不要进行重构，不要安装新依赖。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按以下顺序检查：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一、项目基本情况</span></span>
<span class="line"><span>- 项目技术栈及版本。</span></span>
<span class="line"><span>- 前后端架构。</span></span>
<span class="line"><span>- 模块划分。</span></span>
<span class="line"><span>- 目录结构。</span></span>
<span class="line"><span>- 主要依赖。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>二、运行与开发方式</span></span>
<span class="line"><span>- 如何启动项目？</span></span>
<span class="line"><span>- 如何构建项目？</span></span>
<span class="line"><span>- 如何执行测试？</span></span>
<span class="line"><span>- 是否存在数据库及相关配置？</span></span>
<span class="line"><span>- 是否存在 Docker 或其他运行环境？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三、业务结构</span></span>
<span class="line"><span>- 核心业务模块有哪些？</span></span>
<span class="line"><span>- 模块之间如何调用？</span></span>
<span class="line"><span>- 关键接口在哪里？</span></span>
<span class="line"><span>- 重要数据实体有哪些？</span></span>
<span class="line"><span>- 是否存在第三方系统集成？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四、开发规范</span></span>
<span class="line"><span>- 是否存在 AGENTS.md、CLAUDE.md、.cursor/rules 等规则文件？</span></span>
<span class="line"><span>- 是否存在项目自己的代码规范？</span></span>
<span class="line"><span>- 是否有特殊的命名、目录或架构约束？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>五、风险与注意事项</span></span>
<span class="line"><span>- 哪些模块不应该随意修改？</span></span>
<span class="line"><span>- 哪些操作可能影响生产数据？</span></span>
<span class="line"><span>- 是否存在已知问题？</span></span>
<span class="line"><span>- 哪些信息无法从代码中确认？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六、输出项目接入报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请使用以下格式：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 项目基本信息</span></span>
<span class="line"><span>2. 技术栈与版本</span></span>
<span class="line"><span>3. 目录与模块结构</span></span>
<span class="line"><span>4. 项目启动、构建和测试方式</span></span>
<span class="line"><span>5. 核心业务模块</span></span>
<span class="line"><span>6. 重要接口与数据实体</span></span>
<span class="line"><span>7. 开发规范</span></span>
<span class="line"><span>8. 外部依赖</span></span>
<span class="line"><span>9. 已知风险与注意事项</span></span>
<span class="line"><span>10. 尚未确认的信息</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每项信息标记为：</span></span>
<span class="line"><span>- 已确认：有代码、配置或文档证据。</span></span>
<span class="line"><span>- 待确认：目前无法从现有资料确定。</span></span>
<span class="line"><span>- 人工补充：需要项目维护人员提供。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行约束：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 本轮只读分析，不修改任何文件。</span></span>
<span class="line"><span>2. 不扫描无关目录和大型依赖目录。</span></span>
<span class="line"><span>3. 优先检查项目入口、配置、README、模块结构和关键业务代码。</span></span>
<span class="line"><span>4. 不要把猜测当成事实。</span></span>
<span class="line"><span>5. 不要为了生成报告而重复读取大量相同内容。</span></span>
<span class="line"><span>6. 如果项目规模较大，先输出整体地图，再针对重要模块深入。</span></span>
<span class="line"><span>7. 不需要一次性理解整个项目的所有业务细节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后告诉我：</span></span>
<span class="line"><span>- 当前是否已经具备开发条件？</span></span>
<span class="line"><span>- 如果开始一个新功能，还缺少哪些必要信息？</span></span>
<span class="line"><span>- 哪些内容建议写入项目规则文件？</span></span>
<span class="line"><span>- 哪些内容应该等具体开发任务出现时再分析？</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br></div></div><h3 id="_3-3-老项目接管硬性约束" tabindex="-1">3.3 老项目接管硬性约束 <a class="header-anchor" href="#_3-3-老项目接管硬性约束" aria-label="Permalink to “3.3 老项目接管硬性约束”">​</a></h3><p>以下规则默认适用于老项目：</p><ol><li>不擅自重构原有架构。</li><li>不随意修改已有接口签名。</li><li>不随意升级依赖和框架版本。</li><li>不批量格式化无关文件。</li><li>不把推测出来的业务规则当作真实业务规则。</li><li>不擅自删除已有功能。</li><li>不修改生产数据或执行不可逆操作。</li></ol><p>如果某项开发确实需要突破上述限制，必须先说明原因、影响范围和替代方案，并取得必要授权。</p><h3 id="_3-4-老项目接管完成标准" tabindex="-1">3.4 老项目接管完成标准 <a class="header-anchor" href="#_3-4-老项目接管完成标准" aria-label="Permalink to “3.4 老项目接管完成标准”">​</a></h3><ul><li>已确认项目技术栈及主要版本。</li><li>已找到项目启动和构建方式。</li><li>已了解主要模块结构。</li><li>已找到当前任务相关的核心代码。</li><li>已了解必要的数据库和接口关系。</li><li>已识别已有项目规则。</li><li>已标记未知信息和潜在风险。</li><li>没有擅自修改业务代码。</li><li>没有将未经验证的猜测作为事实。</li></ul><h2 id="四、项目规则文件应该保存什么" tabindex="-1">四、项目规则文件应该保存什么？ <a class="header-anchor" href="#四、项目规则文件应该保存什么" aria-label="Permalink to “四、项目规则文件应该保存什么？”">​</a></h2><p>项目规则文件的作用不是保存整个项目的所有知识，而是让 AI 每次开发都遵守稳定的约束。</p><p>建议优先保存以下内容：</p><table tabindex="0"><thead><tr><th>内容</th><th>是否建议写入</th></tr></thead><tbody><tr><td>技术栈和重要版本</td><td>是</td></tr><tr><td>项目目录约定</td><td>是</td></tr><tr><td>代码命名和开发规范</td><td>是</td></tr><tr><td>启动、构建、测试命令</td><td>是</td></tr><tr><td>禁止擅自修改的模块</td><td>是</td></tr><tr><td>数据库和接口的重要约束</td><td>视项目情况</td></tr><tr><td>某次 Bug 的具体排查过程</td><td>通常不需要</td></tr><tr><td>某次临时需求的业务细节</td><td>通常不需要</td></tr><tr><td>整个项目的所有代码解释</td><td>不需要</td></tr></tbody></table><p>不要把所有项目知识都塞进一个规则文件。</p><p>稳定且每次开发都需要遵守的内容进入规则；具体任务信息随任务提供；专业流程进入 Skill。</p><p>具体配置方式将在第 05 章介绍。</p><h2 id="五、推荐的最小项目资料" tabindex="-1">五、推荐的最小项目资料 <a class="header-anchor" href="#五、推荐的最小项目资料" aria-label="Permalink to “五、推荐的最小项目资料”">​</a></h2><p>项目规模较大、需要长期使用 AI 开发时，可以逐步建立：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>项目根目录/</span></span>
<span class="line"><span>├── README.md</span></span>
<span class="line"><span>├── AGENTS.md                 # 项目级 AI 开发约定（按需）</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>│   └── development/</span></span>
<span class="line"><span>│       ├── project-overview.md</span></span>
<span class="line"><span>│       ├── architecture.md</span></span>
<span class="line"><span>│       └── known-issues.md</span></span>
<span class="line"><span>└── .cursor/</span></span>
<span class="line"><span>    └── rules/                # Cursor 专属规则（按需）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>注意：</p><ul><li>不要求所有项目都采用这个目录。</li><li>不要重复维护相同内容。</li><li>已有文档能承担职责时，优先复用。</li><li>不要为了目录看起来完整而创建空文件。</li><li>不同 AI 工具的配置格式不同，应按工具适配。</li></ul><h2 id="六、什么时候可以开始开发" tabindex="-1">六、什么时候可以开始开发？ <a class="header-anchor" href="#六、什么时候可以开始开发" aria-label="Permalink to “六、什么时候可以开始开发？”">​</a></h2><p>完成项目初始化或接管后，检查以下条件：</p><ol><li>知道项目是什么。</li><li>知道项目如何运行。</li><li>知道如何编译和测试。</li><li>知道开发时需要遵守哪些规则。</li><li>当前任务相关的信息能够继续获取。</li><li>未确认的信息已经明确标注。</li></ol><p><strong>不需要等整个项目完全理解后才开始开发。</strong></p><p>对于新功能，只需要在开始该任务前补充对应业务上下文即可。</p><h2 id="七、常见错误" tabindex="-1">七、常见错误 <a class="header-anchor" href="#七、常见错误" aria-label="Permalink to “七、常见错误”">​</a></h2><h3 id="错误-1-让-ai-一次性扫描整个仓库" tabindex="-1">错误 1：让 AI 一次性扫描整个仓库 <a class="header-anchor" href="#错误-1-让-ai-一次性扫描整个仓库" aria-label="Permalink to “错误 1：让 AI 一次性扫描整个仓库”">​</a></h3><p>问题：耗费大量上下文，产生很多无关信息，反而不利于当前任务。</p><p>正确做法：先了解项目入口和模块地图，再根据任务定位具体代码。</p><h3 id="错误-2-初始化阶段创建大量文档" tabindex="-1">错误 2：初始化阶段创建大量文档 <a class="header-anchor" href="#错误-2-初始化阶段创建大量文档" aria-label="Permalink to “错误 2：初始化阶段创建大量文档”">​</a></h3><p>问题：生成很多没有真实内容、后续也没人维护的文件。</p><p>正确做法：先确定哪些信息会被重复使用，再决定是否沉淀。</p><h3 id="错误-3-ai-没有理解业务就开始开发" tabindex="-1">错误 3：AI 没有理解业务就开始开发 <a class="header-anchor" href="#错误-3-ai-没有理解业务就开始开发" aria-label="Permalink to “错误 3：AI 没有理解业务就开始开发”">​</a></h3><p>问题：技术实现可能正确，但不符合真实业务规则。</p><p>正确做法：将未知业务规则标记为待确认，不能自行编造。</p><h3 id="错误-4-接手老项目时顺手重构" tabindex="-1">错误 4：接手老项目时顺手重构 <a class="header-anchor" href="#错误-4-接手老项目时顺手重构" aria-label="Permalink to “错误 4：接手老项目时顺手重构”">​</a></h3><p>问题：原本只是增加一个功能，却引入大量无关变更和新风险。</p><p>正确做法：严格限制修改范围，先完成当前任务，再讨论独立重构。</p><h2 id="八、本章最终检查" tabindex="-1">八、本章最终检查 <a class="header-anchor" href="#八、本章最终检查" aria-label="Permalink to “八、本章最终检查”">​</a></h2><p>完成本章后，你应该拥有：</p><ul><li>一个可运行、开发命令明确的新项目，或者一份可靠的老项目接入报告。</li><li>一套必要的项目级开发约定。</li><li>一份清楚的项目技术和业务上下文。</li><li>一份已知风险和待确认信息清单。</li></ul><p>下一章将解决另一个最常见的问题：</p><p><strong>如何把开发任务一次性交代清楚，让 AI 不再反复追问、误解需求或遗漏验收条件。</strong></p>`,67)])])}const h=n(e,[["render",i]]);export{m as __pageData,h as default};
